import{_ as i,o as l,c as a,a3 as r}from"./chunks/framework.DjfA6S92.js";const p=JSON.parse('{"title":"Advanced","description":"","frontmatter":{},"headers":[],"relativePath":"guide/advanced.md","filePath":"guide/advanced.md"}'),t={name:"guide/advanced.md"};function o(n,e,h,s,c,d){return l(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h1><p>我们会尽可能地增加<code>Advanced</code>(进阶)这里面的题目的数量和难度，当然也包含很多基础知识点的详细内容。这里的知识点的区分暂时并不是特别明显，之后onion来整理这块儿内容。</p><h2 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to &quot;Browser&quot;">​</a></h2><ul><li><a href="http://web.jobbole.com/94150/" target="_blank" rel="noreferrer">打开一个网页经历了那些过程？</a></li><li><a href="/Interview-Book/Collection/WhiteScreen.html">浏览器加载白屏是什么原因？</a></li><li><a href="/Interview-Book/Collection/DozensOfVisits.html">千万访问量的项目，前端需要注意些什么？</a></li></ul><h2 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;JavaScript&quot;">​</a></h2><p>这一章我们尽量带来较深层的JavaScript语言层次的问题，我们会拿出几个JavaScript较深入的点来讲。</p><ul><li><a href="/Interview-Book/Collection/ExpressionAndStatement.html">表达式和语句有什么区别？如何把语句转换为表达式？</a></li><li>什么叫执行上下文栈(Execution Context Stack)? 一个函数调用会产生多少个上下文环境？如何激活一个上下文，什么叫caller(调用者)，什么叫callee(被调用者)？给你一段代码能否画出执行过程中的上下文堆栈变化？</li><li>执行上下文包括哪些结构(状态/属性)，如何追踪关联代码的执行进度？</li><li>eval在调用的时候有哪些特别的地方？eval函数自身会产生上下文吗？会影响当前的调用上下文吗？</li><li>什么叫变量对象？什么叫活动对象？</li><li><a href="/Interview-Book/Collection/closure_moyu.html">词法作用域是什么？闭包是如何形成的？</a></li><li><code>var foo = function bar () {}</code> 命名函数表达式中(上述的foo函数)bar变量是定义在哪一层作用域的？</li><li><a href="/Interview-Book/Collection/NumberExpression.html"><code>(0, 1, 2)</code> 的结果是什么？</a></li><li><code>var foo = { value: 2, bar: function () { return this.value; }</code> 中<code>(foo.bar, foo.bar)()</code>的<code>this</code>值是什么？<code>(foo.bar = foo.bar)()</code>、<code>(false || foo.bar)()</code>呢?</li></ul><h2 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to &quot;Application&quot;">​</a></h2><p>这里将JavaScript除去基本语言特性之外的东西整理出来，主要是JavaScript在工程上的应用场景，以及一些原理性问题。</p><ul><li><a href="/Interview-Book/Collection/Inherit.html">继承（重点）</a></li><li><a href="https://blog.risingstack.com/writing-a-javascript-framework-execution-timing-beyond-settimeout/" target="_blank" rel="noreferrer">异步（重点）</a></li><li><a href="http://blog.csdn.net/aimingoo/article/details/6105048" target="_blank" rel="noreferrer">new操作符做了什么</a></li><li><a href="https://github.com/Troland/how-javascript-works/blob/master/memory-management.md" target="_blank" rel="noreferrer">JavaScript 内存管理</a></li><li><a href="https://github.com/Liyuk/code-repertory/blob/master/promise/promise.js" target="_blank" rel="noreferrer">实现一个Promise</a></li><li><a href="https://segmentfault.com/a/1190000009591055" target="_blank" rel="noreferrer">js模块化现状？AMD和CMD是什么？</a></li><li>如何在前端解析二进制？流媒体、图片二进制数据怎样渲染到页面上？</li><li><a href="/Interview-Book/Collection/memorization.html">函数记忆是什么？什么场景下使用？（动态规划）</a></li><li>实现一个Lazyman <a href="http://www.cnblogs.com/walls/p/6341614.html" target="_blank" rel="noreferrer">Answer 1</a> <a href="http://web.jobbole.com/89626/" target="_blank" rel="noreferrer">Answer 2</a></li><li><a href="https://jinlong.github.io/2016/04/24/Debouncing-and-Throttling-Explained-Through-Examples/" target="_blank" rel="noreferrer">实现throttle和debounce (必会)</a></li><li>require.js的实现原理，<a href="http://taobaofed.org/blog/2016/09/09/webpack-flow/" target="_blank" rel="noreferrer">webpack的实现原理与loader的实现</a></li><li><a href="https://github.com/jamiebuilds/babel-handbook/blob/master/translations/zh-Hans/plugin-handbook.md" target="_blank" rel="noreferrer">Babel是如何实现的</a></li><li><a href="https://www.zhihu.com/question/274357154" target="_blank" rel="noreferrer">前端工程师可以用编译做什么？</a></li><li><a href="http://louiszhai.github.io/2016/06/13/regexp/" target="_blank" rel="noreferrer">如何用正则表达式实现模板引擎？（正则表达式相关知识点）</a></li></ul><h2 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h2><ul><li>讲一下whatwg标准上的event loop规范。(别说你没看过</li><li>microTask的有哪些，Task的有哪些？（最好答出来所有的</li><li>构思一下利用Task和microTask来完成框架层面的时间调度( 比如vue是如何利用microTask来实现batch update的</li><li>讲一下你对web components的理解</li><li>web worker适合哪些场景</li></ul><h2 id="function-program" tabindex="-1">Function Program <a class="header-anchor" href="#function-program" aria-label="Permalink to &quot;Function Program&quot;">​</a></h2><ul><li><a href="/Interview-Book/Collection/Clojure.html">闭包（重点）</a></li><li><a href="/Interview-Book/Collection/Currying.html">柯里化（Currying）</a></li></ul><h2 id="http" tabindex="-1">HTTP <a class="header-anchor" href="#http" aria-label="Permalink to &quot;HTTP&quot;">​</a></h2><ul><li>http1.0和http1.1的区别</li><li>http请求码有哪些？206、302、303、304、307</li><li>能说下304具体怎样实现吗？</li><li>http缓存逻辑是怎样的？协商缓存与强缓存？Last-Modified / Etag / Expires / Cache-Control ？</li><li>osi七层协议和tcp/ip四层协议</li><li>三次握手和四次握手</li><li>跨域是什么？http协议中如何判断跨域？如何解决跨域问题？</li><li>http2具体内容？SDPY了解么？</li><li>HTTPS如何实现？tsl/ssl是什么？对称加密、非对称加密在什么时候、对什么数据加密？</li><li>DNS劫持是什么？</li><li><a href="/Interview-Book/Collection/SendData.html">浏览器在一次 HTTP 请求中，需要传输一个 4097 字节的文本数据给服务端，可以采用那些方式?</a></li></ul><h2 id="optimization" tabindex="-1">Optimization <a class="header-anchor" href="#optimization" aria-label="Permalink to &quot;Optimization&quot;">​</a></h2><ul><li>首屏优化</li><li>预加载资源、预解析DNS</li><li>懒加载图片怎么做</li><li><a href="/Interview-Book/Collection/iframeUse.html">iframe一般怎么使用？</a></li><li>window.onload、document.ready顺序？iframe会阻塞吗？</li><li>cdn是什么？如何查找最近的cdn？</li><li>gzip、chucked</li><li>前端安全：xss攻击和防范、CSRF、CORS</li><li>硬件加速怎样开启</li><li>优化中会提到缓存的问题，问：静态资源或者接口等如何做缓存优化</li><li>页面DOM节点太多，会出现什么问题？如何优化？</li></ul><h2 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h2><p>这里主要是一些生产中真实存在的问题。</p><ul><li>一个feed流，有哪些展现方式？如果当前页面可视区有5个格子，而你有20条信息需要展示，请问有哪些自动展示的算法？</li><li><a href="https://segmentfault.com/a/1190000004132566" target="_blank" rel="noreferrer">移动端的缓存机制有哪几种？</a></li><li>小程序如何与native通信？react-native实现原理？jsbridge如何实现？</li><li>过万条数据如何加载和渲染？</li><li>如何在前端解析二进制，流媒体、图片二进制数据怎样渲染到页面上？</li><li>如何解析二进制音频、视频？</li><li>文件如何显示上传百分比？</li><li>如何制作一个富文本，需要考虑哪些结构？</li><li>html5的播放器怎么做？视频直播如何在浏览器里面实现？HLS、RTMP</li><li>如何在浏览器里面裁剪图片？如何裁剪视频，对视频做逐帧分析？</li><li>如何实现一个具有引导功能的组件库？</li><li>如何封装一个Form和FormItem，使其能够跟input、select、checkbox、radio等组件进行 数据存储、数据校验（自定义逻辑）、校验反馈？</li><li>echart这类图像库的实现原理？</li><li>i18n的国际化方案应该是怎样的？</li><li>数据埋点的意义是什么？应当针对哪些数据进行埋点？如何构建一个埋点系统？</li><li>小程序的实现原理是什么？<a href="https://github.com/phodal/articles/issues/32" target="_blank" rel="noreferrer">这【五篇】文章将带你深入了解「微信小程序」</a></li><li>小游戏的实现原理是什么？<a href="https://www.zhihu.com/org/cocos-3/posts" target="_blank" rel="noreferrer">Cocos知乎文章：微信小游戏上手</a>、<a href="https://zhuanlan.zhihu.com/p/32749103" target="_blank" rel="noreferrer">深入理解使用白鹭引擎开发微信小游戏的构建机制</a></li><li>mpvue这样h5转小程序的工具的原理是什么？怎样去实现？<a href="https://zhuanlan.zhihu.com/p/34450979" target="_blank" rel="noreferrer">官方宣传文档</a>、<a href="https://www.zhihu.com/question/268421668" target="_blank" rel="noreferrer">如何看待美团开源mpvue</a></li></ul><h2 id="whiteboard" tabindex="-1">Whiteboard <a class="header-anchor" href="#whiteboard" aria-label="Permalink to &quot;Whiteboard&quot;">​</a></h2><p>前端所需要的白板面试题算法难度不高，主要针对JavaScript基础类型的遍历与扩展。<br> 但是如果有喜欢考算法题的，可能会考的很难。所以还是推荐如果有时间的话，可以去把leetcode的easy和medium刷一下，hard可以跳过不看。<br> 国内的面试难度其实很小，有兴趣的朋友看看国外的面试题就知道自己有多么菜了。</p><ul><li>parseQuery</li><li>flatten</li><li><a href="https://github.com/Mountain-Buzhou/Interview-Book/issues/1" target="_blank" rel="noreferrer">乱序算法（Fisher–Yates）</a></li><li><a href="/Interview-Book/Collection/Template.html">模版引擎</a></li><li>反转二叉树</li><li>将两个有序数组合并成为一个有序数组</li><li>全选和单行选中的联动</li><li>数组去重，考虑object、NaN、数字1，弱类型转换</li><li>汉诺塔的实现</li><li>bind</li><li>currying</li><li>一个无重复元素的数组，求所有两数之和为k的组合</li><li>变体题：一个无重复元素的数组，求元素和（元素个数小于n）为k的组合</li><li><a href="/Interview-Book/Collection/Events.html">实现events(发布订阅/观察者模式)</a></li><li>找出数组中最大的两数之差</li><li>棋盘最短路：动态规划、搜索+剪枝、时间优化、空间优化</li><li>二叉树遍历：前序、后序、中序，时间复杂度，空间复杂度O(1)，递归非递归</li><li>双向链表寻找中间的元素，单向链表寻找中间的元素</li><li>查找数组中第k大的数</li></ul><h2 id="system-design" tabindex="-1">System Design <a class="header-anchor" href="#system-design" aria-label="Permalink to &quot;System Design&quot;">​</a></h2><p>这类题目非常繁琐以及复杂，主要出现在高级工程师的最终面试里。对于不同层级的开发人员的回答要求各不相同，但有必要全局地了解整个系统的设计结构和基本概念。</p><ul><li><p>请设计一个前端的组件库，包括组件的分类、具体的内容、API的规范、协作开发的规范。</p></li><li><p><a href="https://github.com/donnemartin/system-design-primer/blob/master/README-zh-Hans.md" target="_blank" rel="noreferrer">System Design Primer 中文</a></p></li><li><p><a href="https://github.com/checkcheckzz/system-design-interview" target="_blank" rel="noreferrer">System Design Interview</a></p></li><li><p><a href="/Interview-Book/Collection/OftenAsked.html">面试常问问题及问答思路</a></p></li></ul>',27)])])}const u=i(t,[["render",o]]);export{p as __pageData,u as default};
